mapper.select:
select distinct info.device_code, info.device_name, info.latitude, info.longitude, info.height, info.model_code as modelId, data.DICT_LABEL as modelName, info.device_model_code, info.location
, oc.tenant_id, oc.customer_name as tenantName
from vm_radar_device_rel_t rel inner join vm_device_info_t info on rel.device_rel_code = info.device_code inner join vm_order_devices osd on osd.device_code = info.device_code and rel.tenant_id = osd.tenant_id and rel.industry_code = osd.industry_code LEFT JOIN vm_order_customer oc on osd.order_code = oc.order_code left join sys_dict_data data on info.model_code = data.DICT_VALUE and data.DICT_TYPE = '103'
and info.delete_flag = '0' and rel.tenant_id = #{tenantId} and rel.radar_device_code = #{radarDeviceCode}
and oc.delete_flag = '0' and oc.ord_status in (0,1,2) and osd.delete_flag = '0' ${dataScope}
and (oc.tenant_id like CONCAT('%', #{tenantIdOrName}, '%') or oc.customer_name like CONCAT('%', #{tenantIdOrName}, '%'))
and info.device_code like CONCAT('%', #{deviceCode}, '%')
and info.device_name like CONCAT('%', #{deviceName}, '%')
and rel.industry_code = #{industryCode}
